-- PART 2 of 4: RLS Policies
-- Paste into Supabase SQL Editor and run AFTER Part 1.

CREATE OR REPLACE FUNCTION has_role(check_role app_role) RETURNS boolean LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$ SELECT exists (SELECT 1 FROM user_roles WHERE user_id = auth.uid() AND role = check_role); $$;
CREATE OR REPLACE FUNCTION is_admin() RETURNS boolean LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$ SELECT has_role('ADMIN'::app_role); $$;
CREATE OR REPLACE FUNCTION owns_provider_profile(p_provider_id uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER STABLE SET search_path = public AS $$ SELECT exists (SELECT 1 FROM provider_profiles WHERE id = p_provider_id AND user_id = auth.uid()); $$;

